'Custom_SMS_Guide_Intro' => 'HTTP API\'si olan her SMS sağlayıcısı bağlanabilir. Sağlayıcınızın API belgelerini açın, uç noktayı, yöntemi ve alan adlarını kopyalayın, ardından değişkenleri kullanarak aşağıda eşleştirin.',
