'Custom_SMS_Guide_Content_Type' => '"json", gövdeyi JSON olarak gönderir (application/json). "form" ise klasik bir HTML formu olarak gönderir (application/x-www-form-urlencoded). Sağlayıcınızın hangisini beklediğini kontrol edin; GET için bu ayar yok sayılır.',
'Custom_SMS_Guide_Sender' => 'Onaylı gönderen kimliğiniz veya gönderici telefon numaranız. Yalnızca {sender} değişkenini doldurur — iletilmesi için gövdede, başlıklarda veya URL\'de kullanılması gerekir.',
