'Custom_SMS_Guide_Headers' => 'Sağlayıcınızın istediği kimlik doğrulama başlıkları, örneğin Authorization = Bearer API_ANAHTARINIZ veya Api-Key = API_ANAHTARINIZ. Content-Type eklemeyin — otomatik olarak ayarlanır.',
'Custom_SMS_Guide_Payload' => 'İstek gövdesi alanları, sağlayıcınızın belgelerindeki adlarla birebir aynı olmalıdır. Değer olarak değişkenleri kullanın, örneğin to = {phone}, message = {message}, from = {sender}.',
